    ///Idiomatic alias for [`Self::VIDEO_PLCMT_SUBTYPE_INTERSTITIAL`]; `Debug` prints the variant name.
    #[allow(non_upper_case_globals)]
    pub const Interstitial: Self = Self::VIDEO_PLCMT_SUBTYPE_INTERSTITIAL;
    ///Idiomatic alias for [`Self::VIDEO_PLCMT_SUBTYPE_NO_CONTENT_STANDALONE`]; `Debug` prints the variant name.
